//! Hybrid search combining full-text and semantic search.//!//! Supports two fusion strategies://! 1. **RRF** (Reciprocal Rank Fusion) — the default, rank-based method.//!    `score = sum(1 / (k + rank))` for each retrieval method.//! 2. **WeightedScore** — converts ranks to scores via `1/rank`, combines with//!    configurable weights (`fts_weight * fts_score + vector_weight * vector_score`),//!    then normalizes to \[0,1\] by dividing by the maximum combined score.//!//! Both strategies combine results from://! - PostgreSQL / libSQL full-text search//! - pgvector / libsql_vector cosine similarity searchuse std::collections::HashMap;use uuid::Uuid;/// Strategy used to fuse FTS and vector search results.#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]pub enum FusionStrategy {    /// Reciprocal Rank Fusion (default). Ignores `fts_weight`/`vector_weight`.    #[default]    Rrf,    /// Weighted score fusion using normalized rank-derived scores.    WeightedScore,}/// Configuration for hybrid search.#[derive(Debug, Clone)]pub struct SearchConfig {    /// Maximum number of results to return.    pub limit: usize,    /// RRF constant (typically 60). Higher values favor top results more.    pub rrf_k: u32,    /// Whether to include FTS results.    pub use_fts: bool,    /// Whether to include vector results.    pub use_vector: bool,    /// Minimum score threshold (0.0-1.0).    pub min_score: f32,    /// Maximum results to fetch from each method before fusion.    pub pre_fusion_limit: usize,    /// Fusion strategy to use when combining results.    pub fusion_strategy: FusionStrategy,    /// Weight for FTS results in `WeightedScore` fusion (default 0.5).    /// Ignored by `Rrf` fusion. For env-based config via    /// `WorkspaceSearchConfig::resolve`, defaults are per-strategy.    pub fts_weight: f32,    /// Weight for vector results in `WeightedScore` fusion (default 0.5).    /// Ignored by `Rrf` fusion. For env-based config via    /// `WorkspaceSearchConfig::resolve`, defaults are per-strategy.    pub vector_weight: f32,}impl Default for SearchConfig {    fn default() -> Self {        Self {            limit: 10,            rrf_k: 60,            use_fts: true,            use_vector: true,            min_score: 0.0,            pre_fusion_limit: 50,            fusion_strategy: FusionStrategy::default(),            fts_weight: 0.5,            vector_weight: 0.5,        }    }}impl SearchConfig {    /// Set the result limit.    pub fn with_limit(mut self, limit: usize) -> Self {        self.limit = limit;        self    }    /// Set the RRF constant.    pub fn with_rrf_k(mut self, k: u32) -> Self {        self.rrf_k = k;        self    }    /// Disable FTS (only use vector search).    pub fn vector_only(mut self) -> Self {        self.use_fts = false;        self.use_vector = true;        self    }    /// Disable vector search (only use FTS).    pub fn fts_only(mut self) -> Self {        self.use_fts = true;        self.use_vector = false;        self    }    /// Set minimum score threshold.    pub fn with_min_score(mut self, score: f32) -> Self {        self.min_score = score.clamp(0.0, 1.0);        self    }    /// Set the fusion strategy.    pub fn with_fusion_strategy(mut self, strategy: FusionStrategy) -> Self {        self.fusion_strategy = strategy;        self    }    /// Set the FTS weight for `WeightedScore` fusion.    ///    /// Non-finite (NaN, ±inf) or negative values are ignored.    pub fn with_fts_weight(mut self, weight: f32) -> Self {        if weight.is_finite() && weight >= 0.0 {            self.fts_weight = weight;        }        self    }    /// Set the vector weight for `WeightedScore` fusion.    ///    /// Non-finite (NaN, ±inf) or negative values are ignored.    pub fn with_vector_weight(mut self, weight: f32) -> Self {        if weight.is_finite() && weight >= 0.0 {            self.vector_weight = weight;        }        self    }}/// A search result with hybrid scoring.#[derive(Debug, Clone)]pub struct SearchResult {    /// Document ID containing this chunk.    pub document_id: Uuid,    /// File path of the source document.    pub document_path: String,    /// Chunk ID.    pub chunk_id: Uuid,    /// Chunk content.    pub content: String,    /// Combined fusion score (0.0-1.0 normalized). Strategy-dependent (RRF or WeightedScore).    pub score: f32,    /// Rank in FTS results (1-based, None if not in FTS results).    pub fts_rank: Option<u32>,    /// Rank in vector results (1-based, None if not in vector results).    pub vector_rank: Option<u32>,}impl SearchResult {    /// Check if this result came from FTS.    pub fn from_fts(&self) -> bool {        self.fts_rank.is_some()    }    /// Check if this result came from vector search.    pub fn from_vector(&self) -> bool {        self.vector_rank.is_some()    }    /// Check if this result came from both methods (hybrid match).    pub fn is_hybrid(&self) -> bool {        self.fts_rank.is_some() && self.vector_rank.is_some()    }}/// Raw result from a single search method.#[derive(Debug, Clone)]pub struct RankedResult {    pub chunk_id: Uuid,    pub document_id: Uuid,    /// File path of the source document.    pub document_path: String,    pub content: String,    pub rank: u32, // 1-based rank}/// Fuse FTS and vector search results using the strategy specified in `config`.////// This is the primary entry point for result fusion. Delegates to/// [`reciprocal_rank_fusion`] or [`weighted_score_fusion`] based on/// `config.fusion_strategy`.